const ArrowLeftIcon: Icon = /* @__PURE__ */ createIcon("arrow-left", iconNode3)

/**
 * Clarifying questions from the agent, one at a time: single choice, multiple choice and free
 * text, with Other, Skip, Back and Next, a 1 of 3 stepper and a summary before sending.
 *
 * Keyboard: arrows move between choices, number keys pick, Enter goes on. Keyboard steps swap
 * instantly; pointer steps slide 8 px with a 180 ms crossfade so the direction reads.
 */
export function Questionnaire({
  questions,
  title = "A few questions before I start",
  value: valueProp,
  defaultValue = {},
  onValueChange,
  onSubmit,
  onDismiss,
  submitted = false,
  submitLabel = "Send answers",
  className,
  ...props
}: QuestionnaireProps) {
  const [valueState, setValueState] = React.useState<QuestionnaireAnswers>(defaultValue)
  const answers = valueProp ?? valueState
  const [step, setStep] = React.useState(0)
  const [motion, setMotion] = React.useState<{ dir: 1 | -1; animate: boolean }>({
    dir: 1,
    animate: false,
  })
  const rootRef = React.useRef<HTMLElement>(null)
  const bodyRef = React.useRef<HTMLDivElement>(null)
  const headingId = React.useId()
  const total = questions.length
  const reviewing = step >= total
  const question = questions[step]
  const answer = question ? answers[question.id] : undefined

  const setAnswer = (id: string, next: QuestionnaireAnswer) => {
    const out = { ...answers, [id]: next }
    if (valueProp === undefined) setValueState(out)
    onValueChange?.(out)
  }

  const go = (to: number, keyboard: boolean) => {
    const target = Math.max(0, Math.min(total, to))
    if (target === step) return
    setMotion({ dir: target > step ? 1 : -1, animate: !keyboard })
    setStep(target)
  }

  // After a step change, keep keyboard users where they were: on the first choice or the field.
  const focusedInside = React.useRef(false)
  React.useEffect(() => {
    if (!focusedInside.current) return
    const body = bodyRef.current
    if (!body) return
    const target =
      body.querySelector<HTMLElement>("[aria-checked=true]") ??
      body.querySelector<HTMLElement>("[data-option-index='0'], textarea, [data-autofocus]")
    target?.focus({ preventScroll: true })
  }, [step])

  const toggle = (q: QuestionnaireQuestion, id: string) => {
    const current = answers[q.id]?.choices ?? []
    let choices: string[]
    if (q.type === "multi") {
      choices = current.includes(id) ? current.filter((c) => c !== id) : [...current, id]
    } else {
      choices = current.includes(id) ? current : [id]
    }
    setAnswer(q.id, { ...answers[q.id], choices, skipped: false })
    if (id === OTHER && choices.includes(OTHER)) {
      // Give the Other field focus once it renders.
      requestAnimationFrame(() =>
        bodyRef.current
          ?.querySelector<HTMLInputElement>("[data-slot=questionnaire-other]")
          ?.focus({ preventScroll: true }),
      )
    }
  }

  const onKeyDown = (event: React.KeyboardEvent) => {
    if (!question || reviewing || question.type === "text") return
    const target = event.target as HTMLElement
    if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) return
    const options = Array.from(
      bodyRef.current?.querySelectorAll<HTMLButtonElement>("[data-option-index]") ?? [],
    )
    const i = options.indexOf(document.activeElement as HTMLButtonElement)
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault()
      const next =
        i === -1
          ? 0
          : event.key === "ArrowDown"
            ? (i + 1) % options.length
            : (i - 1 + options.length) % options.length
      options[next]?.focus()
      return
    }
    const n = Number.parseInt(event.key, 10)
    if (!Number.isNaN(n) && n >= 1 && n <= options.length) {
      event.preventDefault()
      options[n - 1]?.focus()
      options[n - 1]?.click()
      return
    }
    if (event.key === "Enter" && !event.metaKey) {
      const onOption = target.dataset.optionIndex !== undefined
      if (onOption) {
        event.preventDefault()
        // Enter on an unpicked single choice picks it; on a picked one, or in multi, it goes on.
        const picked = target.getAttribute("aria-checked") === "true"
        if (question.type === "single" && !picked) target.click()
        else if (isAnswered(question, answer)) go(step + 1, true)
        else target.click()
      } else if (isAnswered(question, answer) && target.tagName !== "BUTTON") {
        event.preventDefault()
        go(step + 1, true)
      }
    }
  }

  /* --- Submitted: compact read-only summary ----------------------------------------------- */

  if (submitted) {
    const answered = questions.filter((q) => isAnswered(q, answers[q.id])).length
    return (
      <section
        aria-labelledby={headingId}
        data-slot="questionnaire"
        data-state-submitted=""
        className={cn("flex flex-col gap-2", className)}
        {...props}
      >
        <p id={headingId} className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) flex items-center gap-2">
          <CheckIcon aria-hidden="true" className="text-(color:--chatcn-fg) size-3.5" />
          Answered {answered} of {total} {total === 1 ? "question" : "questions"}
        </p>
        <dl className="border-(color:--chatcn-border) ms-1.5 flex flex-col gap-1.5 border-s ps-4">
          {questions.map((q) => (
            <div key={q.id} className="text-[0.8125rem]/[1.25rem] flex min-w-0 flex-col">
              <dt className="text-(color:--chatcn-fg-subtle)">{q.title}</dt>
              <dd className="text-(color:--chatcn-fg)">
                {describeAnswer(q, answers[q.id]) ?? (
                  <span className="text-(color:--chatcn-fg-subtle)">Skipped</span>
                )}
              </dd>
            </div>
          ))}
        </dl>
      </section>
    )
  }

  const stepClass = motion.animate
    ? cn(
        "ease-(--chatcn-ease-out) transition-[opacity,translate] duration-180",
        "starting:opacity-0 motion-reduce:starting:translate-x-0",
        motion.dir === 1
          ? "starting:translate-x-2 rtl:starting:-translate-x-2"
          : "starting:-translate-x-2 rtl:starting:translate-x-2",
      )
    : undefined

  return (
    <section
      ref={rootRef}
      aria-labelledby={headingId}
      data-slot="questionnaire"
      onFocus={() => {
        focusedInside.current = true
      }}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget as Node))
          focusedInside.current = false
      }}
      onKeyDown={onKeyDown}
      className={cn(
        "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) flex min-w-0 flex-col overflow-hidden",
        "text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) forced-colors:outline-1 forced-colors:outline-solid",
        className,
      )}
      {...props}
    >
      <header className="flex min-h-11 items-center gap-3 ps-3.5 pe-2 pt-1">
        <CircleHelpIcon aria-hidden="true" className="text-(color:--chatcn-fg-subtle) size-4 shrink-0" />
        <h3 id={headingId} className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) min-w-0 flex-1">
          <span className="block truncate">{title}</span>
        </h3>
        <nav aria-label="Questions" className="flex items-center gap-2">
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) tabular-nums" aria-live="polite">
            {reviewing ? "Review" : `${step + 1} of ${total}`}
          </span>
          <ol className="flex items-center gap-1">
            {questions.map((q, i) => {
              const done = isAnswered(q, answers[q.id]) || answers[q.id]?.skipped
              const current = i === step
              return (
                <li key={q.id}>
                  <button
                    type="button"
                    aria-label={`Question ${i + 1}${done ? ", answered" : ""}`}
                    aria-current={current ? "step" : undefined}
                    onClick={(event) => go(i, event.detail === 0)}
                    className="chatcn-focus rounded-(--chatcn-radius-xs) group/seg grid h-6 w-5 place-items-center"
                  >
                    <span
                      className={cn(
                        "block h-0.5 w-full rounded-full",
                        "ease-(--chatcn-ease-standard) transition-colors duration-150",
                        current
                          ? "bg-(color:--chatcn-accent)"
                          : done
                            ? "bg-(color:--chatcn-fg-subtle)"
                            : "bg-(color:--chatcn-alpha-500) group-hover/seg:bg-(color:--chatcn-fg-faint)",
                      )}
                    />
                  </button>
                </li>
              )
            })}
          </ol>
        </nav>
        {onDismiss ? (
          <Button size="xs" onClick={onDismiss} className="ms-1">
            Skip all
          </Button>
        ) : null}
      </header>

      <div ref={bodyRef} className="px-2 pb-2">
        {reviewing ? (
          <div key="review" className={cn("flex flex-col gap-3 px-1.5 pt-2", stepClass)}>
            <p className="text-[0.9375rem]/[1.5rem] tracking-[-0.006em] text-(color:--chatcn-fg) font-medium text-balance">
              Check your answers
            </p>
            <dl className="flex flex-col">
              {questions.map((q, i) => {
                const text = describeAnswer(q, answers[q.id])
                return (
                  <div
                    key={q.id}
                    className="border-(color:--chatcn-border)/70 flex min-w-0 items-start gap-3 border-t py-2.5 first:border-t-0"
                  >
                    <div className="flex min-w-0 flex-1 flex-col gap-0.5">
                      <dt className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle)">{q.title}</dt>
                      <dd
                        className={cn(
                          "text-[0.875rem]/[1.25rem] tracking-[-0.003em]",
                          text ? "text-(color:--chatcn-fg)" : "text-(color:--chatcn-fg-subtle)",
                        )}
                      >
                        {text ?? "Skipped"}
                      </dd>
                    </div>
                    <Button
                      size="xs"
                      onClick={(event) => go(i, event.detail === 0)}
                      aria-label={`Edit answer to ${q.title}`}
                    >
                      Edit
                    </Button>
                  </div>
                )
              })}
            </dl>
          </div>
        ) : question ? (
          <div key={question.id} className={cn("flex flex-col gap-3 pt-2", stepClass)}>
            <div className="flex flex-col gap-1 px-1.5">
              <p
                id={`${headingId}-q`}
                className="text-[0.9375rem]/[1.5rem] tracking-[-0.006em] text-(color:--chatcn-fg) font-medium text-balance"
              >
                {question.title}
              </p>
              {question.description ? (
                <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) text-pretty">
                  {question.description}
                </p>
              ) : null}
            </div>

            {question.type === "text" ? (
              <div className="px-1.5">
                <textarea
                  aria-labelledby={`${headingId}-q`}
                  value={answer?.text ?? ""}
                  rows={3}
                  placeholder={question.placeholder ?? "Type your answer…"}
                  onChange={(event) =>
                    setAnswer(question.id, { text: event.target.value, skipped: false })
                  }
                  onKeyDown={(event) => {
                    // Enter goes on, Shift+Enter is a newline, and IME composition never sends.
                    if (event.key !== "Enter" || event.shiftKey || event.nativeEvent.isComposing)
                      return
                    event.preventDefault()
                    if (isAnswered(question, answer) || !question.required) go(step + 1, true)
                  }}
                  className={cn(
                    "rounded-(--chatcn-radius-md) bg-(color:--chatcn-inset) text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) w-full resize-none px-3 py-2.5",
                    "placeholder:text-(color:--chatcn-fg-subtle) shadow-[inset_0_0_0_1px_var(--chatcn-alpha-300)] outline-none",
                    "focus-visible:shadow-[inset_0_0_0_1px_var(--chatcn-border-strong)]",
                    "field-sizing-content max-h-48 min-h-20",
                  )}
                />
              </div>
            ) : (
              // biome-ignore lint/a11y/useAriaPropsSupportedByRole: the role is group or radiogroup, both take a label
              <div
                role={question.type === "multi" ? "group" : "radiogroup"}
                aria-labelledby={`${headingId}-q`}
                className="flex flex-col gap-0.5"
              >
                {(question.options ?? []).map((option, i) => (
                  <OptionRow
                    key={option.id}
                    index={i}
                    tabbable={i === tabIndexFor(question, answer)}
                    label={option.label}
                    description={option.description}
                    multi={question.type === "multi"}
                    checked={answer?.choices?.includes(option.id) ?? false}
                    onToggle={() => toggle(question, option.id)}
                  />
                ))}
                {question.allowOther ? (
                  <OptionRow
                    index={question.options?.length ?? 0}
                    tabbable={(question.options?.length ?? 0) === tabIndexFor(question, answer)}
                    label="Other"
                    multi={question.type === "multi"}
                    checked={answer?.choices?.includes(OTHER) ?? false}
                    onToggle={() => toggle(question, OTHER)}
                  >
                    {answer?.choices?.includes(OTHER) ? (
                      <div className="ps-11.5 pe-2.5 pb-2.5">
                        <input
                          data-slot="questionnaire-other"
                          value={answer?.other ?? ""}
                          aria-label="Other answer"
                          placeholder={question.placeholder ?? "Describe it in a few words…"}
                          onChange={(event) =>
                            setAnswer(question.id, { ...answer, other: event.target.value })
                          }
                          onKeyDown={(event) => {
                            if (event.key !== "Enter" || event.nativeEvent.isComposing) return
                            event.preventDefault()
                            if (isAnswered(question, answer)) go(step + 1, true)
                          }}
                          className={cn(
                            "rounded-(--chatcn-radius-sm) bg-(color:--chatcn-card) text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) h-8 w-full px-2.5",
                            "placeholder:text-(color:--chatcn-fg-subtle) shadow-[inset_0_0_0_1px_var(--chatcn-alpha-400)] outline-none",
                            "focus-visible:shadow-[inset_0_0_0_1px_var(--chatcn-border-strong)]",
                          )}
                        />
                      </div>
                    ) : null}
                  </OptionRow>
                ) : null}
              </div>
            )}
          </div>
        ) : null}
      </div>

      <footer className="border-(color:--chatcn-border)/70 flex items-center gap-1.5 border-t py-2 ps-2 pe-2">
        {step > 0 ? (
          <Button size="sm" onClick={(event) => go(step - 1, event.detail === 0)}>
            <ArrowLeftIcon className="rtl:-scale-x-100" />
            Back
          </Button>
        ) : null}
        <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) ms-1.5 hidden items-center gap-1 sm:flex pointer-coarse:hidden">
          {!reviewing && question?.type !== "text" ? (
            <>
              <Kbd>1</Kbd>
              <span>to</span>
              <Kbd>{(question?.options?.length ?? 0) + (question?.allowOther ? 1 : 0)}</Kbd>
              <span>to pick</span>
            </>
          ) : null}
        </span>
        <span className="flex-1" />
        {reviewing ? (
          <Button size="sm" variant="solid" onClick={() => onSubmit?.(answers)}>
            {submitLabel}
          </Button>
        ) : question ? (
          <>
            {!question.required ? (
              <Button
                size="sm"
                onClick={(event) => {
                  setAnswer(question.id, { skipped: true })
                  go(step + 1, event.detail === 0)
                }}
              >
                Skip
              </Button>
            ) : null}
            <Button
              size="sm"
              variant="solid"
              disabled={!isAnswered(question, answer)}
              onClick={(event) => go(step + 1, event.detail === 0)}
            >
              {step === total - 1 ? "Review" : "Next"}
              <Kbd className="bg-(color:--chatcn-bg)/15 text-(color:--chatcn-bg)/80 -me-1 shadow-none pointer-coarse:hidden">
                ↵
              </Kbd>
            </Button>
          </>
        ) : null}
      </footer>
    </section>
  )
}

