function QuestionnaireDemo() {
  const [answers, setAnswers] = React.useState<QuestionnaireAnswers>({})
  const [submitted, setSubmitted] = React.useState(false)
  return (
    <div className="flex w-full max-w-lg flex-col items-start gap-3">
      <Questionnaire
        className="w-full"
        title="A few questions before I add CSV export"
        questions={QUESTIONS}
        value={answers}
        onValueChange={setAnswers}
        submitted={submitted}
        onSubmit={() => setSubmitted(true)}
        onDismiss={() => setSubmitted(true)}
      />
      {submitted ? (
        <button
          type="button"
          onClick={() => {
            setAnswers({})
            setSubmitted(false)
          }}
          className="chatcn-focus rounded-(--chatcn-radius-sm) text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) hover:text-(color:--chatcn-fg) underline underline-offset-4 transition-colors"
        >
          Ask again
        </button>
      ) : null}
    </div>
  )
}

